      await inDirectory({ groups: many, roles: roles({ rolePrivileges: [{ privilegeName: "GROUPS_ALL" }] }) }, () =>
        listManageableGroups(actor),
      )
    ).length,
    5,
  );
  assert.deepEqual(
    await inDirectory({ groups: many, roles: roles({ rolePrivileges: [] }) }, () => listManageableGroups(actor)),
    [],
  );
  assert.deepEqual(
    await inDirectory({ groups: many, roles: {}, assignments: [] }, () => listManageableGroups(actor)),
    [],
  );

  // Denied calls are reported (reconnect only for rejected credentials) and never retried.
  const original = console.error;
  console.error = () => {};
  try {
    for (const status of [401, 403, 503]) {
      const directory = fakeDirectory({ status });
      try {
        for (const call of [
          () => isWorkspaceEmailAvailable(actor, email),
          () => listManageableGroups(actor),
        ]) {
          await assert.rejects(
            call(),
            (error: unknown) =>
              error instanceof WorkspaceUnavailable && error.reconnect === (status === 401),
          );
        }
        assert.equal(directory.calls.length, 2);
      } finally {
        directory.restore();
      }
    }
  } finally {
    console.error = original;
  }
}

